python_examples.basic_request:
import requests

response = requests.post(
    'http://localhost:8011/api/v1/query',
    json={'query': 'Who is Iron Man?', 'top_k': 5}
)
print(response.json())

python_examples.streaming_request:
import requests
import json

response = requests.post(
    'http://localhost:8011/api/v1/query',
    json={'query': 'Who is Iron Man?', 'stream': True},
    stream=True
)

for line in response.iter_lines():
    if line:
        data = json.loads(line.decode('utf-8').replace('data: ', ''))
        if data['type'] == 'token':
            print(data['content'], end='', flush=True)
